@push('styles')
<style>
.bm-shell{max-width:1280px;margin:auto}.bm-hero,.bm-card{background:#fff;border:1px solid #e2e9f0;border-radius:.85rem;box-shadow:0 8px 22px rgba(30,65,95,.06)}.bm-hero{padding:1.5rem;display:flex;gap:1rem;align-items:center;justify-content:space-between;animation:bm-enter .35s ease both}.bm-kicker{display:block;color:#188ae2;font-size:.73rem;font-weight:700;letter-spacing:.08em;text-transform:uppercase}.bm-hero h1{margin:.15rem 0;font-size:1.6rem}.bm-hero p{margin:0;color:#64748b}.bm-logo{width:48px;animation:bm-logo 8s linear infinite}.bm-metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem;margin:1rem 0}.bm-metric{padding:1.1rem;background:#f7fbff;border:1px solid #e2e9f0;border-radius:.75rem;animation:bm-enter .4s ease both}.bm-metric:nth-child(2){animation-delay:.06s}.bm-metric:nth-child(3){animation-delay:.12s}.bm-metric strong{display:block;font-size:1.65rem;color:#1f3d5a}.bm-card{padding:1.25rem;margin-top:1rem}.bm-toolbar{display:flex;gap:.75rem;align-items:center;justify-content:space-between;flex-wrap:wrap}.bm-table{margin:1rem 0 0}.bm-table tbody tr{transition:.18s ease}.bm-table tbody tr:hover{transform:translateY(-2px);box-shadow:0 5px 12px rgba(24,138,226,.09)}.bm-status{font-size:.75rem;border-radius:99px;padding:.35rem .6rem;font-weight:700;background:#eef6fd;color:#188ae2}.bm-status.ok{background:#eafaf4;color:#17815c}.bm-status.warn{background:#fff6df;color:#a26a00}.bm-status.danger{background:#fff0f0;color:#c24141}.bm-flow{display:flex;gap:.5rem;flex-wrap:wrap;margin-top:.7rem}.bm-flow span{padding:.4rem .65rem;background:#f5f5f5;border-radius:99px;font-size:.8rem}.bm-flow .is-current{background:#188ae2;color:#fff}.bm-form-section{padding:1rem;border:1px solid #e2e9f0;border-radius:.75rem;margin:1rem 0;background:#fbfdff}.bm-form-section h2{font-size:1.05rem}.bm-detail-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:.8rem}.bm-fact{background:#f7fbff;border-radius:.65rem;padding:.8rem}.bm-fact span{display:block;font-size:.75rem;color:#64748b}.bm-fact strong{display:block;margin-top:.2rem}.bm-timeline{border-left:2px solid #dcecf8;margin:.8rem 0;padding-left:1rem}.bm-timeline-item{position:relative;padding:0 0 1rem}.bm-timeline-item:before{content:'';position:absolute;left:-1.42rem;top:.2rem;width:.7rem;height:.7rem;border-radius:50%;background:#188ae2}.bm-save{position:relative}.bm-save:disabled:after{content:'';display:inline-block;width:.8rem;height:.8rem;border:2px solid #fff;border-right-color:transparent;border-radius:50%;margin-left:.5rem;animation:bm-spin .7s linear infinite}@keyframes bm-enter{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}@keyframes bm-logo{to{transform:rotate(360deg)}}@keyframes bm-spin{to{transform:rotate(360deg)}}@media(max-width:640px){.bm-hero{align-items:flex-start}.bm-metrics{grid-template-columns:1fr}.bm-hero .btn{width:100%}}@media(prefers-reduced-motion:reduce){.bm-hero,.bm-metric,.bm-table tbody tr,.bm-logo,.bm-save:disabled:after{animation:none;transition:none}}
</style>
@endpush
